/// Result of applying one probe to the writer-fence state.
#[derive(Debug, PartialEq, Eq)]
pub enum SafeFrontierDecision {
    AdvanceTo(String),
    HoldAt(String),
    HoldExisting,
}

/// Apply the writer-fence rule without touching PostgreSQL.
pub fn transition_writer_fences(
    state: &mut FrontierProbeState,
    probe: &FrontierProbe,
) -> Result<SafeFrontierDecision, crate::lsn::LsnParseError> {
    let candidate = crate::lsn::Lsn::parse(&probe.candidate_lsn)?;
    let previous_candidate = state
        .previous_candidate_lsn
        .as_deref()
        .map(|lsn| Ok((lsn.to_string(), crate::lsn::Lsn::parse(lsn)?)))
        .transpose()?;
    let last_safe = state
        .last_safe_lsn
        .as_deref()
        .map(|lsn| Ok((lsn.to_string(), crate::lsn::Lsn::parse(lsn)?)))
        .transpose()?;
    let previous_fences = state
        .writer_fences
        .iter()
        .map(|(xid, fence)| {
            Ok((
                *xid,
                fence
                    .as_deref()
                    .map(|lsn| Ok((lsn.to_string(), crate::lsn::Lsn::parse(lsn)?)))
                    .transpose()?,
            ))
        })
        .collect::<Result<HashMap<_, _>, crate::lsn::LsnParseError>>()?;

    let next_fences = probe
        .active_xids
        .iter()
        .map(|xid| {
            (
                *xid,
                previous_fences
                    .get(xid)
                    .cloned()
                    .unwrap_or_else(|| previous_candidate.clone()),
            )
        })
        .collect::<HashMap<_, _>>();
        "SELECT confirmed_flush_lsn >= $2::pg_lsn \
